<script setup lang="ts">
import { getCurrentInstance, nextTick, watch } from 'vue';
import { useDisplay } from '../../../shared/useDisplay';
import { type Row, formatTime } from '../../../shared/domain';
import { api, baseUrl, choosePhotos, uploadMedia } from '../platform';
const props=defineProps<{user:Row|null;foreground:boolean}>();
const instance=getCurrentInstance();
function toggle(key:string,event:any){form.value[key]=key==='status'?(event.detail.value?'published':'draft'):Boolean(event.detail.value);}
const {data,error,message,mediaError,loading,busy,paused,index,managing,assets,editing,removing,form,uploading,uploadProgress,staff,slides,current,maxMonth,maxCategory,next,failed,load,manage,edit,upload,save}=useDisplay(()=>props.user,api,()=>props.foreground);
watch([paused,current,()=>props.foreground],async()=>{await nextTick();if(current.value?.type==='video'){const video=uni.createVideoContext('display-video',instance?.proxy);if(paused.value||!props.foreground)video.pause();else video.play();}});
async function photo(){try{const files=await choosePhotos(1);if(files[0])await upload(progress=>uploadMedia(files[0].source,'display','',files[0].name,progress));}catch(e){error.value=(e as Error).message;}}
function video(){uni.chooseVideo({sourceType:['album'],compressed:true,success:result=>{void upload(progress=>uploadMedia(result.tempFilePath,'display','','活动视频.mp4',progress));},fail:e=>{if(!e.errMsg?.includes('cancel'))error.value='无法选择视频，请检查相册权限';}});}
</script>
<template><view class="display-mobile"><view class="title">乡情大屏</view><view class="intro">电脑打开可全屏展示活动数据、照片和视频。</view><view class="display-actions"><button class="outline" :disabled="loading" @click="load">刷新数据</button><button v-if="staff" class="outline" @click="manage">管理播放素材</button></view><view v-if="error" class="error">{{error}}</view><view v-if="message" class="notice-line">{{message}}</view>
 <view class="mobile-stage"><view class="stage-heading">沭阳之家 · 活动记录</view><view class="stage-note">{{loading?'正在更新…':data?'更新于 '+formatTime(data.updatedAt):'正在连接看板…'}}</view><template v-if="data"><view class="stage-metrics"><view><text>{{data.members}}</text><view>家人 / 人</view></view><view><text>{{data.events}}</text><view>活动 / 场</view></view><view><text>{{data.hours}}</text><view>服务 / 小时</view></view></view><view class="stage-media"><template v-if="current"><image v-if="current.type==='image'" :src="baseUrl()+'/media/'+current.mediaId" mode="aspectFit" @error="failed"/><video v-else id="display-video" :key="current.mediaId" :src="baseUrl()+'/media/'+current.mediaId" :autoplay="!paused&&foreground" :muted="true" :controls="true" :loop="slides.length===1" :show-fullscreen-btn="true" @ended="!paused&&next()" @error="failed"/></template><view v-else class="stage-empty">这里还没有照片或视频。<view>管理员发布素材后，会在这里轮播。</view></view></view><view v-if="current" class="stage-caption"><view>{{current.title}}</view><text>{{current.caption}}</text></view><view class="display-actions stage-controls"><button :disabled="!slides.length" @click="next(-1)">上一条</button><button :disabled="!slides.length" @click="paused=!paused">{{paused?'继续播放':'暂停轮播'}}</button><button :disabled="!slides.length" @click="next()">下一条</button></view><view class="stage-note">{{slides.length?index+1:0}} / {{slides.length}} · 每分钟更新数据</view><view v-if="mediaError" class="stage-warning">{{mediaError}}</view>
 <view class="stage-chart-title">近六个月活动</view><view class="stage-note">按已发布活动的开始月份统计</view><view class="stage-columns"><view v-for="month in data.months" :key="month.label"><text>{{month.value}}</text><view class="stage-column-space"><view :style="{height:Math.max(2,month.value/maxMonth*100)+'%'}"/></view><text>{{month.label.slice(5)}}月</text></view></view><view class="stage-chart-title">活动类型</view><view v-for="category in data.categories" :key="category.label" class="stage-bar"><view>{{category.label||'其他'}} · {{category.value}}场</view><view class="stage-bar-track"><view :style="{width:category.value/maxCategory*100+'%'}"/></view></view><view v-if="!data.categories.length" class="stage-note">首场活动发布后，这里会留下足迹。</view><view class="stage-chart-title">最近的活动</view><view v-for="event in data.upcoming" :key="event.id" class="stage-event"><view>{{event.title}}</view><text>{{formatTime(event.startsAt)}} · {{event.location}}</text></view><view v-if="!data.upcoming.length" class="stage-note">目前还没有活动安排。</view></template><view v-else-if="error" class="stage-empty">数据暂不可用，请刷新重试。</view></view>
 <view v-if="managing&&staff" class="panel"><view class="card-title">播放素材</view><view class="meta">JPG／PNG最多8MB，MP4最多15MB，建议H.264编码。视频按原时长播放，照片按设置秒数轮播。</view><view class="display-actions"><button class="primary" :disabled="busy||uploading" @click="edit()">新增照片／视频</button><button class="outline" :disabled="busy||uploading" @click="managing=false;editing=false">收起管理</button></view><view v-if="editing"><view class="field"><view class="field-label">标题</view><input v-model="form.title" maxlength="80" placeholder="2至80字"/></view><view class="field"><view class="field-label">说明</view><textarea v-model="form.caption" maxlength="300"/></view><view class="display-actions"><button class="outline" :disabled="busy||uploading" @click="photo">选择照片</button><button class="outline" :disabled="busy||uploading" @click="video">选择视频</button></view><view class="meta">{{uploading?'上传中 '+uploadProgress+'%':form.mediaId?'已选择：'+(form.mediaName||form.type):'请上传一份素材'}}</view><view class="field"><view class="field-label">播放顺序（0至999，小的在前）</view><input v-model="form.position" type="number"/></view><view class="field"><view class="field-label">照片停留秒数（5至60）</view><input v-model="form.seconds" type="number"/></view><view class="switch-row"><text>公开展示</text><switch :checked="form.status==='published'" @change="toggle('status',$event)"/></view><view class="switch-row"><text>已确认拥有展示权限，内容适合公开</text><switch :checked="form.consent" @change="toggle('consent',$event)"/></view><view class="display-actions"><button class="primary" :disabled="busy||uploading||!form.mediaId" @click="save()">保存素材</button><button class="outline" :disabled="busy||uploading" @click="editing=false">取消</button></view></view><view v-if="removing" class="notice-line">确认移除“{{removing.title}}”？<view class="display-actions"><button class="primary" :disabled="busy" @click="save(true)">确认移除</button><button class="outline" :disabled="busy" @click="removing=null">取消</button></view></view><view v-for="asset in assets" :key="asset.id" class="display-asset"><view>{{asset.position}} · {{asset.title}}</view><view class="meta">{{asset.type==='video'?'视频':'照片'}} · {{asset.status==='published'?'公开展示':'草稿'}}</view><view class="display-actions"><button class="outline" :disabled="busy||uploading" @click="edit(asset)">编辑</button><button class="text-button" :disabled="busy||uploading" @click="removing=asset">移除</button></view></view><view v-if="!assets.length" class="meta">还没有素材，上传第一张活动照片吧。</view></view>
</view></template>
<style scoped>
.display-actions{display:flex;gap:16rpx;flex-wrap:wrap;align-items:center;margin:24rpx 0}.display-actions button{font-size:14px;padding:12rpx 22rpx;line-height:1.6;margin:0;min-height:44px}.mobile-stage{background:#102334;color:#edf4f5;border-radius:28rpx;padding:30rpx;margin:24rpx 0;overflow:hidden}.stage-heading{font-size:24px;color:#f4e5c6;line-height:1.5}.stage-note{font-size:12px;line-height:1.8;color:#b7c9d3;margin-top:12rpx}.stage-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16rpx;margin:32rpx 0}.stage-metrics>view{border-left:2px solid #bfa571;padding-left:18rpx;font-size:12px;color:#b7c9d3}.stage-metrics text{font:30px Georgia,serif;color:#f2dba8}.stage-media{height:360rpx;background:#091823;border-radius:18rpx;overflow:hidden}.stage-media image,.stage-media video{width:100%;height:100%}.stage-empty{padding:60rpx 20rpx;text-align:center;font-size:18px;color:#e7d4ad;line-height:1.9}.stage-empty view{font-size:13px;color:#b7c9d3;margin-top:18rpx}.stage-caption{margin-top:22rpx;font-size:18px;overflow-wrap:anywhere}.stage-caption text{display:block;font-size:13px;color:#b7c9d3;line-height:1.8;margin-top:10rpx}.stage-controls button{background:#21394b;color:#e4edf1;border:1px solid #526a7a;border-radius:12rpx;flex:1;padding-inline:8rpx}.stage-warning{color:#ffd6ad;font-size:14px;line-height:1.8}.stage-chart-title{font-size:17px;color:#edf4f5;margin-top:40rpx}.stage-columns{height:300rpx;display:flex;gap:20rpx;margin:24rpx 0}.stage-columns>view{flex:1;display:flex;flex-direction:column;align-items:center;gap:12rpx;min-width:0}.stage-columns text{font-size:12px;color:#c5d6e0}.stage-column-space{height:100%;width:65%;min-height:0;display:flex;align-items:flex-end}.stage-column-space view{width:100%;background:#8fb5bc;border-radius:8rpx 8rpx 0 0}.stage-bar{margin-top:24rpx;font-size:14px}.stage-bar-track{height:14rpx;background:#ffffff16;border-radius:8rpx;margin-top:16rpx;overflow:hidden}.stage-bar-track view{height:100%;background:#d1b678}.stage-event{margin-top:20rpx;font-size:15px;line-height:1.8}.stage-event text{font-size:12px;color:#b7c9d3}.display-asset{border-top:1px solid var(--ui-line);padding-top:24rpx;margin-top:24rpx;overflow-wrap:anywhere}.display-mobile textarea{width:100%;box-sizing:border-box}.display-mobile .switch-row text{flex:1}
</style>
